'use client';
import {useEffect,useRef,useState} from 'react';
import {hotelRpc,type Membership} from '@/lib/pilot';
import {afterDays} from '@/lib/rates';
import {readPerformance,summarizePerformance,performanceDayRows,performanceHeaders,performanceExportRows,type PerformanceReport} from '@/lib/historical-performance';
import {downloadReport} from '@/lib/report-export';
import {ReportCsvCopy} from '@/components/report-csv-copy';
export function HistoricalPerformance({membership,businessDate}:{membership:Membership;businessDate:string}){
 const [start,setStart]=useState(afterDays(businessDate,-7)),[end,setEnd]=useState(businessDate),[report,setReport]=useState<PerformanceReport|null>(null),[busy,setBusy]=useState(false),[error,setError]=useState('');
 const alive=useRef(true),sequence=useRef(0);useEffect(()=>{alive.current=true;return()=>{alive.current=false;sequence.current++}},[]);
 const allowed=['owner','manager'].includes(membership.role);
 const fresh=allowed&&report?.tenant_id===membership.tenant_id&&report?.property_id===membership.property_id&&report?.start===start&&report?.end===end&&!busy;
 async function load(e:React.FormEvent){e.preventDefault();if(!allowed)return;const seq=++sequence.current;let timer:ReturnType<typeof setTimeout>|undefined;setBusy(true);setError('');setReport(null);try{const value=await Promise.race([hotelRpc('historical_performance_report',{p_tenant:membership.tenant_id,p_property:membership.property_id,p_start:start,p_end:end}),new Promise<never>((_,reject)=>{timer=setTimeout(()=>reject(new Error('The report took too long to load. Please try again.')),30000)})]);const data=readPerformance(value,{tenant:membership.tenant_id,property:membership.property_id,start,end});if(alive.current&&seq===sequence.current)setReport(data)}catch(e){if(alive.current&&seq===sequence.current)setError(e instanceof Error?e.message:'Unable to load historical performance.')}finally{if(timer!==undefined)clearTimeout(timer);if(alive.current&&seq===sequence.current)setBusy(false)}}
 if(!allowed)return <p>Historical performance is available to owners and managers.</p>;
 const summary=fresh&&report?summarizePerformance(report):null;
 return <section className="card pilot-reports"><h2>Historical overnight performance</h2><p>Preserved closed-day revenue and inventory. Overnight guest counts are captured at close where available; older closes may not have them. Original overnight rates exclude same-day charges, taxes, property fees and posted corrections, which are shown separately.</p><form className="pilot-report-filters" onSubmit={load}><label className="field">From<input type="date" required value={start} disabled={busy} onChange={e=>setStart(e.target.value)}/></label><label className="field">Until (exclusive)<input type="date" required value={end} disabled={busy} onChange={e=>setEnd(e.target.value)}/></label><button className="primary" disabled={busy}>{busy?'Loading…':'Load historical performance'}</button></form>{error&&<p className="pilot-error" role="alert">{error}</p>}{summary&&report?<div key={report.generated_at}><p>{summary.closed_days} closed days · {summary.unclosed_days} unclosed days · {summary.missing_inventory_days} closed days without complete capacity.</p><p>Capacity means the effective selling capacity reviewed at close. Period ADR is original overnight accommodation divided by occupied room-nights. RevPAR divides it by effective unit-nights, and occupancy divides occupied nights by effective unit-nights. Period rates use totals, not averages of daily rates. Net accommodation after posted corrections includes overnight, same-day and other accommodation plus signed corrections; taxes and property fees are excluded.</p>{summary.reconciliation_required&&<p className="pilot-error">Charges or adjustments still require reconciliation. Original allocations remain unchanged.</p>}{summary.capacity_shortfall&&<p className="pilot-error">Occupied nights exceed saved effective capacity on at least one day. Review the inventory configuration.</p>}<div className="pilot-report-totals">{[['Occupied nights in closed days',summary.occupied_nights],['Effective unit-nights',summary.effective_unit_nights],['Occupancy on effective capacity %',summary.occupancy_percent],['Original overnight ADR USD',summary.original_overnight_adr],['Original overnight RevPAR USD',summary.original_overnight_revenue_per_effective_unit],['Net accommodation after posted corrections USD',summary.net_accommodation_usd]].map(([label,value])=><div key={label}><span>{label}</span><strong>{value??'Unavailable'}</strong></div>)}</div><button className="secondary" onClick={()=>{try{downloadReport('historical-performance-'+report.start+'-'+report.end,performanceExportRows(report))}catch{setError('Unable to download the report. Use the copyable CSV.')}}}>Export historical CSV</button><ReportCsvCopy rows={()=>performanceExportRows(report)}/><div className="pilot-table-wrap"><table className="pilot-table"><caption>Preserved daily performance · {report.start} to {report.end} exclusive</caption><thead><tr>{performanceHeaders.map(h=><th scope="col" key={h}>{h}</th>)}</tr></thead><tbody>{performanceDayRows(report).map((row,i)=><tr key={report.days[i].service_date}>{row.map((cell,j)=><td key={j}>{cell===null?'Unavailable':String(cell)}</td>)}</tr>)}</tbody></table></div></div>:<p>Load dates to view the preserved report.</p>}</section>;
}
